define({"topics":[{"title":"Doing DQA calibration","shortdesc":"<p class=\"shortdesc\">The DQA tool determines proper gradient polarity and proper gradient wiring by scanning a series of axial and coronal images of the DQA III phantom.<\/p>","href":"t_UsingtheDQAIICalibrationTool_2.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e68881","topics":[]},{"title":"Troubleshooting the Daily Quality Assurance (DQA) II tool","shortdesc":"<p class=\"shortdesc\">If problems are encountered while using the Daily Quality Assurance (DQA) calibration procedure, refer to the following guidelines for troubleshooting.<\/p>","href":"t_TroubleshootingTheDQAIITool.html","attributes":{"data-id":"id_2001636"},"menu":{"hasChildren":false},"tocID":"id_2001636-d46e68986","topics":[]}]});